SET @chofer_id = (SELECT `id_empleado` FROM `Empleado` WHERE `nombres` LIKE '%GIANFRANCO%' OR `apellidos` LIKE '%GIANFRANCO%' LIMIT 1);
SET @vehiculo_id = (SELECT `id_vehiculo` FROM `Vehiculo` WHERE `placa` = 'F2Z877' LIMIT 1);
