SET @chofer_id = (SELECT `id_empleado` FROM `Empleado` WHERE `nombres` LIKE '%OBED%' OR `apellidos` LIKE '%OBED%' LIMIT 1);
SET @vehiculo_id = (SELECT `id_vehiculo` FROM `Vehiculo` WHERE `placa` = 'D1O763' LIMIT 1);
